#!/usr/bin/env node
// Review first, then approve:
//   node cli.js redact <input.txt>                                  -> prints the review table only
//   node cli.js redact <input.txt> --approve --out safe.txt --map map.json
//   node cli.js restore <ai-answer.txt> --map map.json             -> prints the answer with real values
const fs = require("fs");
const { redact, restore, reviewTable } = require("./src/redact");

const [cmd, input, ...rest] = process.argv.slice(2);
const opt = (name) => {
  const i = rest.indexOf(name);
  return i >= 0 ? rest[i + 1] : undefined;
};
const usage = () => {
  console.error("Usage: node cli.js redact <file> [--approve --out <file> --map <file>] | node cli.js restore <file> --map <file>");
  process.exit(2);
};

if (!input || !["redact", "restore"].includes(cmd)) usage();
const text = fs.readFileSync(input, "utf8");

if (cmd === "restore") {
  const mapFile = opt("--map");
  if (!mapFile) usage();
  process.stdout.write(restore(text, JSON.parse(fs.readFileSync(mapFile, "utf8"))));
  process.exit(0);
}

const result = redact(text);
console.log(reviewTable(result.findings));

if (!rest.includes("--approve")) {
  console.log("\nNothing written. Check the table above, then re-run with --approve --out <file> to save the redacted text.");
  process.exit(0);
}

const out = opt("--out");
if (!out) usage();
const mapFile = opt("--map");

// Never overwrite: "wx" fails if the file exists, so a typo can't replace the
// original input or an earlier mapping. Check both paths before writing either.
for (const f of [out, mapFile].filter(Boolean)) {
  if (fs.existsSync(f)) {
    console.error(`Refusing to overwrite ${f}. Choose a new file name.`);
    process.exit(1);
  }
}
fs.writeFileSync(out, result.text, { flag: "wx" });
console.log(`\nRedacted text written to ${out}.`);
if (mapFile) {
  fs.writeFileSync(mapFile, JSON.stringify(result.mapping, null, 2), { flag: "wx" });
  console.log(`Mapping written to ${mapFile}. It contains the real values: keep it local and delete it when done.`);
}

// Replaces sensitive values with stable placeholders ([EMAIL_1], [CARD_1]...)
// before text is pasted into an AI tool, and can put the real values back
// into the AI's answer afterwards. Detection is pattern-based and runs
// locally; nothing is sent anywhere.

function luhn(digits) {
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    let d = Number(digits[digits.length - 1 - i]);
    if (i % 2 === 1) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
  }
  return sum % 10 === 0;
}

const onlyDigits = (s) => s.replace(/\D/g, "");

// Order matters: secrets and emails first, then cards, IPs, and phones last
// (the phone pattern is the loosest).
const DETECTORS = [
  { type: "SECRET", re: /-----BEGIN [A-Z ]*PRIVATE KEY-----/g },
  { type: "SECRET", re: /\b(?:sk|pk|rk)-[A-Za-z0-9_-]{16,}\b/g },
  { type: "SECRET", re: /\bgh[pousr]_[A-Za-z0-9]{20,}\b/g },
  { type: "SECRET", re: /\bAKIA[0-9A-Z]{16}\b/g },
  { type: "SECRET", re: /\bxox[abprs]-[A-Za-z0-9-]{10,}\b/g },
  { type: "EMAIL", re: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g },
  { type: "CARD", re: /\b\d(?:[ -]?\d){12,18}\b/g, accept: (m) => luhn(onlyDigits(m)) },
  { type: "IP", re: /\b(?:\d{1,3}\.){3}\d{1,3}\b/g },
  {
    type: "PHONE",
    re: /\+?\(?\d[\d\s().-]{7,}\d/g,
    accept: (m) => {
      const n = onlyDigits(m).length;
      return n >= 9 && n <= 15 && !/^\d{4}-\d{2}-\d{2}/.test(m.trim());
    },
  },
];

function redact(text) {
  const placeholders = new Map(); // original -> placeholder
  const counters = {};
  const findings = [];

  const lines = String(text).split("\n").map((line, i) => {
    let out = line;
    for (const d of DETECTORS) {
      out = out.replace(d.re, (match) => {
        if (/^\[[A-Z]+_\d+\]$/.test(match)) return match;
        if (d.accept && !d.accept(match)) return match;
        let ph = placeholders.get(match);
        if (!ph) {
          counters[d.type] = (counters[d.type] || 0) + 1;
          ph = `[${d.type}_${counters[d.type]}]`;
          placeholders.set(match, ph);
        }
        findings.push({ type: d.type, line: i + 1, placeholder: ph, original: match });
        return ph;
      });
    }
    return out;
  });

  const mapping = Object.fromEntries([...placeholders].map(([orig, ph]) => [ph, orig]));
  return { text: lines.join("\n"), findings, mapping };
}

// Put real values back into text that contains placeholders (e.g. the AI's reply).
function restore(text, mapping) {
  return String(text).replace(/\[[A-Z]+_\d+\]/g, (ph) => (ph in mapping ? mapping[ph] : ph));
}

// Shows enough to recognise a value without printing it in full.
function preview(value) {
  const v = String(value);
  return v.length <= 6 ? "*".repeat(v.length) : `${v.slice(0, 2)}${"*".repeat(Math.min(v.length - 4, 12))}${v.slice(-2)}`;
}

function reviewTable(findings) {
  if (findings.length === 0) return "No sensitive values found. Review the text yourself before sharing — detection is pattern-based.";
  return [
    "| Line | Type | Replaced with | Original (masked) |",
    "| --- | --- | --- | --- |",
    ...findings.map((f) => `| ${f.line} | ${f.type} | ${f.placeholder} | ${preview(f.original)} |`),
  ].join("\n");
}

module.exports = { luhn, redact, restore, preview, reviewTable };

const test = require("node:test");
const assert = require("node:assert");
const { luhn, redact, restore, preview, reviewTable } = require("../src/redact");

test("emails, Luhn-valid cards, IPs, phones and API keys are replaced", () => {
  const { text } = redact(
    "mail ada@example.com card 4242 4242 4242 4242 ip 203.0.113.42 call +44 20 7946 0958 key sk-EXAMPLEONLY-not-a-real-key-0000"
  );
  assert.strictEqual(text, "mail [EMAIL_1] card [CARD_1] ip [IP_1] call [PHONE_1] key [SECRET_1]");
});

test("the same value always gets the same placeholder", () => {
  const { text, findings } = redact("a@example.com\nb@example.com\na@example.com");
  assert.strictEqual(text, "[EMAIL_1]\n[EMAIL_2]\n[EMAIL_1]");
  assert.deepStrictEqual(findings.map((f) => f.line), [1, 2, 3]);
});

test("numbers that are not sensitive are left alone", () => {
  assert.strictEqual(luhn("4242424242424241"), false);
  const input = "order 100045, total 129.99, date 2026-10-14, card-like 4242 4242 4242 4241";
  assert.strictEqual(redact(input).text, input);
});

test("restore puts real values back and leaves unknown placeholders", () => {
  const { mapping } = redact("contact ada@example.com");
  assert.strictEqual(restore("Reply to [EMAIL_1] about [CARD_9]", mapping), "Reply to ada@example.com about [CARD_9]");
});

test("the review table masks originals", () => {
  const { findings } = redact("ada.lovelace@example.com");
  const table = reviewTable(findings);
  assert.match(table, /\| 1 \| EMAIL \| \[EMAIL_1\] \| ad\*+om \|/);
  assert.ok(!table.includes("ada.lovelace@example.com"));
  assert.strictEqual(preview("1234"), "****");
  assert.match(reviewTable([]), /No sensitive values found/);
});
